import{_ as r,o as e,c as s,a3 as a}from"./chunks/framework.Cvi1TL8V.js";const g=JSON.parse('{"title":"Chapter 7.0 Milvus 3.0：从 2.x 走过来","description":"","frontmatter":{},"headers":[],"relativePath":"Milvus/chapter7/7.0-Milvus3.0.md","filePath":"Milvus/chapter7/7.0-Milvus3.0.md","lastUpdated":1793868172000}'),o={name:"Milvus/chapter7/7.0-Milvus3.0.md"};function l(n,t,i,p,h,u){return e(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="chapter-7-0-milvus-3-0-从-2-x-走过来" tabindex="-1">Chapter 7.0 Milvus 3.0：从 2.x 走过来 <a class="header-anchor" href="#chapter-7-0-milvus-3-0-从-2-x-走过来" aria-label="Permalink to &quot;Chapter 7.0 Milvus 3.0：从 2.x 走过来&quot;">​</a></h1><p>Milvus 3.0 正式版（v3.0.0）于 2026 年 7 月 29 日发布。本篇说明它和 2.x 的核心区别，以及本章各篇的安排；单个功能的细节都在后面各篇展开，完整的功能清单见官方发布说明（<a href="https://milvus.io/docs/zh/release_notes.md" target="_blank" rel="noreferrer">https://milvus.io/docs/zh/release_notes.md</a>）。</p><h2 id="_7-0-1-3-0-的新功能" tabindex="-1">7.0.1 3.0 的新功能 <a class="header-anchor" href="#_7-0-1-3-0-的新功能" aria-label="Permalink to &quot;7.0.1 3.0 的新功能&quot;">​</a></h2><p><strong>数据可以不搬进库里。</strong> 这是 3.0 最大的变化：数据在湖上，检索就在湖上做，不再拷一份进库。外部 Collection 直接引用湖存储上的文件，原地建索引并检索，零拷贝、只读，并通过增量刷新实现同步。</p><p><strong>更多计算下推进服务端。</strong> 过去只能把一大批结果取回客户端，自己在应用里排序、统计、重排；3.0 把这些搬进了内核：按价格、时间这类字段排序，在服务端直接完成；一次搜索同时带回「每个类目命中多少条」这类统计；Function Chain（函数链）把多个重排器串成一条链，在同一次请求里完成重排、排序和候选裁剪，无需客户端编排。</p><p><strong>Schema 可以在线改。</strong> 加字段、补数据、删字段都直接在线上做，不用重建 Collection，也不用停服务。最典型的场景是换嵌入模型：给存量数据补算新向量，过去得新建集合把数据搬一遍，现在在原集合上加一列就能补——向量可以配个函数由后台慢慢算，也可以由外部任务算好写回。</p><p><strong>稀疏索引和写入引擎换代。</strong> 稀疏向量检索有了新一代索引 SINDI：同样召回率下索引更小、查询更快，全文检索和混合检索直接受益。写入链路也换了新引擎 Woodpecker——可作为独立服务运行，通过增加副本水平扩展写入容量。</p><p><strong>升级要留意默认行为。</strong> 新能力不随升级自动生效：Storage V3 默认关闭，需手动开启；新索引算法需手动提升目标索引版本才生效。3.0 部署可回滚至 2.6，但一旦启用会更改序列化数据格式的功能（如 Storage V3），回滚就不可再行。</p><p><strong>参考文档</strong>：<a href="https://milvus.io/docs/zh/release_notes.md" target="_blank" rel="noreferrer">Milvus 发布说明</a></p><h2 id="_7-0-2-本章各篇安排" tabindex="-1">7.0.2 本章各篇安排 <a class="header-anchor" href="#_7-0-2-本章各篇安排" aria-label="Permalink to &quot;7.0.2 本章各篇安排&quot;">​</a></h2><p>本章按「基础 → 实战」主线组织，另配一篇深入与进阶（内容均来自官方文档，出处见各节）：</p><ul><li><strong>7.1 环境升级（基础）</strong>——从 2.6 升级到 3.0 的步骤，以及启用新功能要改的两个配置；</li><li><strong>7.2 外部集合与快照（实战）</strong>——湖上文件原地检索，快照隔离与回滚；含 MySQL 等常见数据源能不能接的核查；</li><li><strong>7.3 数据模型与检索增强（实战）</strong>——排序、聚合、分面、重排、多向量、TEXT、在线改列；</li><li><strong>7.4 索引与性能选择（实战）</strong>——3.0 的三类新索引：SINDI 稀疏（全文/稀疏 Embedding）、FAISS 直通（现成 Faiss 配方）、DiskANN 磁盘（晚期交互/超内存），外加一张「负载→索引」选型表；</li><li><strong>7.5 端到端实战（实战）</strong>——把 3.0 的升级点串成一条链路跑通；</li><li><strong>7.6 深入与进阶</strong>——正文刻意没展开的原理与底层集中在这里：FunctionChain 的 L0/L1/L2 执行位置（对应 7.3）、稀疏倒排遍历算法（对应 7.4.1）、存储与写入引擎和 Storage V3 清单（对应 7.1.2 / 7.2 / 7.4）。</li></ul><p><strong>参考文档</strong>：<a href="https://milvus.io/docs/zh/" target="_blank" rel="noreferrer">Milvus 文档</a> · <a href="https://milvus.io/docs/zh/release_notes.md" target="_blank" rel="noreferrer">Milvus 发布说明</a></p><blockquote><p><strong>下一章</strong>：<a href="./7.1-Milvus3.0环境升级.html">7.1　Milvus 3.0 环境升级</a></p></blockquote>',14)])])}const _=r(o,[["render",l]]);export{g as __pageData,_ as default};
